-- دليل المبيعات في صفحة المسار (طلب المالك 2026-08-09) — تحديث دليل المسار
update public.kb_articles
set body_md = body_md || E'\n\n## دليل المبيعات: خرائط الخدمات وخطواتها\nأسفل لوحة المسار قسم قابل للطي «دليل المبيعات» — مرجعك السريع أثناء مكالمة البيع: اختر تصنيف الخدمة فترى منهجية تسليمها الرباعية (تحليل ← توليد ← تسويق ← تكيّف) بمراحلها وخطواتها الفعلية من كتيبات التنفيذ، مع نمط العمل (اشتراك دوري أم مشروع بمراحل) والمدة التقديرية وعدد اعتمادات العميل. عِد العميل بما ننفذه حرفياً — والمدد تقديرات كتيب لا التزام تعاقدي؛ الالتزام في النطاق وعرض السعر.',
    indexed_at = null
where title = 'دليل المسار: من عميل محتمل إلى عقد';
